import 'dart:io';

import 'package:drift/drift.dart';

import 'package:drift/native.dart';

import 'package:path/path.dart' as p;

import 'package:path_provider/path_provider.dart';

// Generated by Drift with `dart run build_runner build`.
part 'database.g.dart';

// All application data is stored as entries in this journal.
class Journal extends Table {
  // SQLite-generated entry ID, also used by object links.
  IntColumn get id => integer().autoIncrement()();

  // Unix timestamp in seconds.
  IntColumn get time => integer()();

  // Entry flags; bit 8 is reserved for the sync service.
  IntColumn get flags => integer().withDefault(const Constant(0))();

  // Numeric JournalType value.
  IntColumn get type => integer()();

  // JSON payload containing the entry's data.
  TextColumn get body => text()();
}

@DriftDatabase(tables: [Journal])
class AppDb extends _$AppDb {
  AppDb() : super(_openConnection());

  // Increment when the database schema changes.
  @override
  int get schemaVersion => 1;
}

// Open the database lazily in the application documents directory.
LazyDatabase _openConnection() {
  return LazyDatabase(() async {
    final dir = await getApplicationDocumentsDirectory();
    final file = File(p.join(dir.path, 'polyrutina.sqlite'));

    // Keep database work off the UI isolate.
    return NativeDatabase.createInBackground(
      file,
      setup: (rawDb) {
        rawDb.execute('PRAGMA journal_mode = WAL');
        rawDb.execute('PRAGMA synchronous = NORMAL');
      },
    );
  });
}
